DROP TABLE IF EXISTS `quartermaster_reward_items`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `quartermaster_reward_items` (
  `reward_id` mediumint unsigned NOT NULL,
  `pool_id` mediumint unsigned NOT NULL,
  `reward_kind` tinyint unsigned NOT NULL DEFAULT '1' COMMENT '1 item, 2 money in copper',
  `item_id` mediumint unsigned NOT NULL DEFAULT '0',
  `min_amount` mediumint unsigned NOT NULL DEFAULT '1',
  `max_amount` mediumint unsigned NOT NULL DEFAULT '1',
  `weight` mediumint unsigned NOT NULL DEFAULT '1',
  `roll_group` varchar(32) NOT NULL DEFAULT 'DEFAULT',
  `class_mask` int unsigned NOT NULL DEFAULT '0',
  `require_usable` tinyint unsigned NOT NULL DEFAULT '0',
  `prefer_unowned` tinyint unsigned NOT NULL DEFAULT '0',
  PRIMARY KEY (`reward_id`),
  KEY `idx_quartermaster_reward_items_pool` (`pool_id`),
  CONSTRAINT `fk_quartermaster_reward_items_pool` FOREIGN KEY (`pool_id`) REFERENCES `quartermaster_reward_pools` (`pool_id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
